// Test claims for the Validation & Fraud Decision Agent.
// Each case has an input (sent to the agent) and what we expect back.
// Rule scores and warning signs are exact; routes that the LLM adjustment
// could change list every acceptable route.
const claim = {
  claim_id: 'TST-000',
  incident_date: '2026-10-10',
  incident_location: 'Tunis',
  description: 'Rear-ended at a red light. Rear bumper and trunk lid damaged.',
  claimed_amount: 1450,
  photo_count: 3,
  photo_taken_dates: ['2026-10-10', '2026-10-10', '2026-10-11'],
  photo_reused: false,
  has_invoice: true,
};
const validation = { valid: true, reasons: [] };
const visual = {
  damage_severity: 2, damaged_parts: ['pare-choc arriere', 'coffre'], impact_zone: 'arriere',
  matches_description: true, mismatch_reason: '', pre_existing_damage_signs: false, pre_existing_reason: '',
  same_vehicle_across_photos: true, suspicious_image_flags: [],
};
const invoice = {
  totals_match: true, total: 1450,
  line_items: [
    { part: 'Pare-choc arrière', type: 'part', quantity: 1, unit_price: 620 },
    { part: 'Coffre', type: 'part', quantity: 1, unit_price: 480 },
    { part: "Main d'oeuvre", type: 'labor', quantity: 5, unit_price: 70 },
  ],
};
const policy_rag = { coverage_status: 'COVERED', cited_clauses: ['Section 4.2'], reasoning: 'Collision damage is covered.', flagged_exclusions: [] };

// Tiny test photos (16x16 JPEGs). A has EXIF date 2026-10-10 and is saved in the
// "photo hashes" Data Table under the old claim CLM-H001 by "Seed Test Photo"; B is dated 2026-09-01;
// C has no EXIF date. D (dated 2026-09-01) and E (no date) are only used by the tests,
// so they are never reused by a real claim.
const PHOTO = {
  A: '',
  B: '',
  C: '',
  D: '',
  E: '',
};
const photos = (...names) => Object.fromEntries(names.map((n, i) => [
  `photo_${i + 1}`, { data: PHOTO[n], mimeType: 'image/jpeg', fileName: `photo_${n}.jpg`, fileExtension: 'jpg' },
]));

const V = (name, claimChanges, expect, binary) => ({ name, input: { stage: 'validate', claim: { ...claim, ...claimChanges } }, expect, binary });
const D = (name, changes, expect) => ({
  name,
  input: { stage: 'decide', claim, validation, visual, invoice, policy_rag, ...changes(JSON.parse(JSON.stringify({ claim, validation, visual, invoice, policy_rag }))) },
  expect,
});

const cases = [
  // Validate stage
  V('V1 valid claim', {}, { valid: true }),
  V('V5 missing description', { description: '' }, { valid: false, reason: 'description' }),
  V('V6 no photos', { photo_count: 0 }, { valid: false, reason: 'photo_count' }),
  V('V7 future incident date', { incident_date: '2099-01-01' }, { valid: false, reason: 'future' }),
  V('V8 invoice missing', { has_invoice: false }, { valid: false, reason: 'invoice' }),
  V('V11 photo files: dates read, nothing reused', {}, { valid: true, photos_checked: 2, photo_reused: false, photo_dates: ['2026-09-01'] }, photos('D', 'E')),
  V('V12 photo files: reused photo caught', {}, { valid: true, photos_checked: 1, photo_reused: true, reused_from: ['CLM-H001'], photo_dates: ['2026-10-10'] }, photos('A')),

  // Decide stage
  D('D1 clean claim', () => ({}), { rule_score: 0, signs: [], route: ['auto_approve', 'human_review'] }),
  D('D2 reused photo', d => ({ claim: { ...d.claim, photo_reused: true } }), { rule_score: 40, signs: ['PHOTO_REUSED'], route: ['fraud_investigation'] }),
  D('D3 damage mismatch', d => ({ visual: { ...d.visual, matches_description: false, mismatch_reason: 'Front damage, rear impact described' } }), { rule_score: 20, signs: ['DAMAGE_MISMATCH'], route: ['human_review'] }),
  D('D4 mismatch + bad invoice maths', d => ({ visual: { ...d.visual, matches_description: false }, invoice: { ...d.invoice, totals_match: false } }), { rule_score: 35, signs: ['DAMAGE_MISMATCH', 'INVOICE_ARITHMETIC'], route: ['human_review', 'fraud_investigation'] }),
  D('D5 photo before incident', d => ({ claim: { ...d.claim, photo_taken_dates: ['2026-09-01'] } }), { rule_score: 15, signs: ['PHOTO_BEFORE_INCIDENT'], route: ['auto_approve', 'human_review'] }),
  D('D6 invoiced parts not in photos', d => ({ invoice: { ...d.invoice, line_items: [...d.invoice.line_items, { part: 'Phare avant', type: 'part' }, { part: 'Capot', type: 'part' }] } }), { rule_score: 10, signs: ['PART_NOT_VISIBLE'], route: ['auto_approve', 'human_review'] }),
  D('D7 pre-existing damage', d => ({ visual: { ...d.visual, pre_existing_damage_signs: true, pre_existing_reason: 'Rust in scratches' } }), { rule_score: 10, signs: ['PRE_EXISTING_DAMAGE'], route: ['auto_approve', 'human_review'] }),
  D('D8 everything wrong (score capped at 60)', d => ({
    claim: { ...d.claim, photo_reused: true, photo_taken_dates: ['2026-09-01'] },
    visual: { ...d.visual, matches_description: false, pre_existing_damage_signs: true },
    invoice: { ...d.invoice, totals_match: false },
  }), { rule_score: 60, signs: ['PHOTO_REUSED', 'DAMAGE_MISMATCH', 'INVOICE_ARITHMETIC', 'PHOTO_BEFORE_INCIDENT', 'PRE_EXISTING_DAMAGE'], route: ['fraud_investigation'] }),
  D('D9 amount above auto-approval limit', d => ({ claim: { ...d.claim, claimed_amount: 5000 } }), { rule_score: 0, signs: [], route: ['human_review'] }),
  D('D10 coverage excluded', d => ({ policy_rag: { ...d.policy_rag, coverage_status: 'EXCLUDED' } }), { rule_score: 0, signs: [], route: ['human_review'] }),
  D('D11 visual agent result missing', () => ({ visual: undefined }), { rule_score: 0, signs: [], route: ['human_review'], missing: ['visual'] }),
  D('D12 visual agent returned an error', () => ({ visual: { error: true, error_message: 'model failed' } }), { rule_score: 0, signs: [], route: ['human_review'], missing: ['visual'] }),
  D('D13 reused photo found by the validate stage', d => ({ validation: { ...d.validation, photo_checks: { photo_reused: true, reused_from_claims: ['CLM-H001'], photo_taken_dates: ['2026-10-10'] } } }), { rule_score: 40, signs: ['PHOTO_REUSED'], route: ['fraud_investigation'] }),
  D('D14 early photo date found by the validate stage', d => ({ validation: { ...d.validation, photo_checks: { photo_reused: false, reused_from_claims: [], photo_taken_dates: ['2026-09-01'] } } }), { rule_score: 15, signs: ['PHOTO_BEFORE_INCIDENT'], route: ['human_review'] }),
  D('D15 incident story implausible (plausibility agent)', () => ({ plausibility: { agent: 'incident_plausibility', score: 25, weighted_score: 25, warning_signs: [{ code: 'WEATHER_OR_LIGHT_CONTRADICTION', points: 15, confidence: 'high' }, { code: 'PLACE_FEATURE_MISSING', points: 10, confidence: 'high' }], summary: '2 warning signs, 25 points: weather or light contradiction; place feature missing.' } }), { rule_score: 20, signs: ['INCIDENT_IMPLAUSIBLE'], route: ['human_review'] }),
  D('D16 plausibility agent failed', () => ({ plausibility: { error: 'Incident Plausibility: missing input fields: incident_datetime' } }), { rule_score: 0, signs: [], route: ['human_review'], missing: ['plausibility'] }),
  D('D17 plausibility agent found nothing', () => ({ plausibility: { agent: 'incident_plausibility', score: 0, weighted_score: 0, warning_signs: [], summary: 'No warning signs.' } }), { rule_score: 0, signs: [], route: ['auto_approve', 'human_review'] }),
  D('D18 invoiced parts compared by code', d => ({
    visual: { ...d.visual, damaged_parts: ['rear_bumper', 'trunk_lid_tailgate'] },
    invoice: { ...d.invoice, line_items: [
      { part: 'Pare-choc AR', type: 'part', part_code: 'rear_bumper' },
      { part: 'Phare avant gauche', type: 'part', part_code: 'headlight_left' },
      { part: 'Feu arriere', type: 'part', part_code: null },
      { part: "Main d'oeuvre", type: 'labor', part_code: null },
    ] },
  }), { rule_score: 5, signs: ['PART_NOT_VISIBLE'], route: ['auto_approve', 'human_review'] }),
  D('D19 amount unknown (invoice total not read)', d => ({ claim: { ...d.claim, claimed_amount: undefined } }), { rule_score: 0, signs: [], route: ['human_review'] }),
];

return cases.map((c, i) => ({
  json: { ...c.input, claim: { ...c.input.claim, claim_id: `TST-${c.name.split(" ")[0]}` }, _test_name: c.name, _expect: c.expect },
  ...(c.binary ? { binary: c.binary } : {}),
}));

// Compares what the agent returned with what each test expected.
const cases = $('Test Cases').all();
const sameSet = (a, b) => [...a].sort().join(',') === [...b].sort().join(',');

const rows = $input.all().map((item, i) => {
  const t = cases[i].json;
  const e = t._expect;
  const out = item.json;
  const problems = [];

  if (out.error) {
    const msg = typeof out.error === 'string' ? out.error : (out.error.message || JSON.stringify(out.error));
    problems.push(`agent crashed: ${msg}`);
  }

  if ('valid' in e && out.valid !== e.valid) problems.push(`valid is ${out.valid}, expected ${e.valid}`);
  if (e.reason && !(out.reasons || []).some(r => r.toLowerCase().includes(e.reason.toLowerCase()))) {
    problems.push(`no reason mentioning "${e.reason}" (got: ${(out.reasons || []).join('; ') || 'none'})`);
  }
  if ('rule_score' in e && out.rule_score !== e.rule_score) problems.push(`rule_score is ${out.rule_score}, expected ${e.rule_score}`);
  if (e.signs) {
    const got = (out.warning_signs || []).map(s => s.code);
    if (!sameSet(got, e.signs)) problems.push(`warning signs are [${got.join(', ')}], expected [${e.signs.join(', ')}]`);
  }
  if (e.route && !e.route.includes(out.route)) problems.push(`route is ${out.route}, expected ${e.route.join(' or ')}`);
  if (e.missing && !sameSet(out.missing_inputs || [], e.missing)) problems.push(`missing_inputs is [${(out.missing_inputs || []).join(', ')}], expected [${e.missing.join(', ')}]`);
  const pc = out.photo_checks ?? {};
  if ('photos_checked' in e && pc.photos_checked !== e.photos_checked) problems.push(`photos_checked is ${pc.photos_checked}, expected ${e.photos_checked}`);
  if ('photo_reused' in e && pc.photo_reused !== e.photo_reused) problems.push(`photo_reused is ${pc.photo_reused}, expected ${e.photo_reused}`);
  if (e.reused_from && !sameSet(pc.reused_from_claims || [], e.reused_from)) problems.push(`reused_from_claims is [${(pc.reused_from_claims || []).join(', ')}], expected [${e.reused_from.join(', ')}]`);
  if (e.photo_dates && !sameSet(pc.photo_taken_dates || [], e.photo_dates)) problems.push(`photo_taken_dates is [${(pc.photo_taken_dates || []).join(', ')}], expected [${e.photo_dates.join(', ')}]`);
  if (out.llm_error) problems.push(`LLM problem: ${out.llm_error}`);

  return {
    json: {
      test: t._test_name,
      result: problems.length ? 'FAIL' : 'PASS',
      problems: problems.join(' | '),
      route: out.route ?? (out.valid === undefined ? '' : (out.valid ? 'valid' : 'rejected')),
      risk_score: out.risk_score ?? '',
      llm_adjustment: out.llm_adjustment ?? '',
    },
  };
});

const failed = rows.filter(r => r.json.result === 'FAIL').length;
rows.unshift({ json: { test: 'SUMMARY', result: failed ? `${failed} FAILED` : 'ALL PASSED', problems: `${rows.length - failed}/${rows.length} tests passed`, route: '', risk_score: '', llm_adjustment: '' } });
return rows;
